const msgText = msg.req.query.msg;
const to = msg.req.query.to;
if (!msgText || !to) {
    msg.statusCode = 400;
    msg.payload = { error: 'Missing msg or to parameter' };
    return msg;
}
msg.headers = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer ' + flow.get('whatsapp_token')
};
msg.payload = {
    messaging_product: 'whatsapp',
    to,
    type: 'text',
    text: { body: msgText }
};
msg.url = `https://graph.facebook.com/v18.0/${flow.get('phone_id')}/messages`;
return msg;
